<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>出荷作業 | 販売管理</title>
  <style>
    :root{font-family:Inter,"Noto Sans JP",system-ui,sans-serif;color:#172033;background:#f5f7fb;font-size:13px}*{box-sizing:border-box}body{margin:0}header{height:52px;padding:0 20px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #dce4ee}header h1{font-size:15px;font-weight:800;padding-left:10px;letter-spacing:.02em}a{color:#075ecf;text-decoration:none}main{padding:12px 18px}.layout{display:grid;grid-template-columns:420px minmax(620px,1fr);gap:12px}.card{background:#fff;border:1px solid #dce4ee;border-radius:6px;overflow:hidden}.head{padding:11px 14px;border-bottom:1px solid #e7edf4;display:flex;align-items:center;justify-content:space-between;gap:8px}h1,h2,p{margin:0}h2{font-size:15px}.muted{color:#64748b;font-size:11px}.filter{padding:10px 13px;border-bottom:1px solid #e7edf4}.task-list{display:grid;grid-auto-rows:max-content;align-content:start}.task{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:start;padding:11px 13px;border:0;border-bottom:1px solid #edf1f6;background:#fff;text-align:left;cursor:pointer;font:inherit;overflow:hidden}.task:hover,.task.selected{background:#e7f0ff}.task.selected{box-shadow:inset 3px 0 #0b6ff6}.task-top,.actions{display:flex;align-items:center;justify-content:flex-start;gap:8px}.task-main{min-width:0}.task-side{min-width:154px;display:grid;grid-template-columns:auto auto;column-gap:8px;row-gap:2px;align-items:baseline;text-align:left;color:#64748b;font-size:10px;line-height:1.35}.task-side span{text-align:right}.task-side strong{color:#172033;font-size:11px;font-weight:800;text-align:left;white-space:nowrap}.task-number{font-size:12px;font-weight:800;color:#075ecf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.task-customer{font-weight:700;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.task-meta{margin-top:5px;color:#64748b;font-size:10px}.badge{display:inline-block;max-width:100%;padding:2px 6px;border-radius:999px;background:#eaf3ff;color:#075ecf;font-size:10px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.badge.progress{background:#fff4dd;color:#9a6700}.badge.done{background:#e7f7ed;color:#137333}.badge.danger{background:#fee4e2;color:#b42318}.work-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 15px;border-bottom:1px solid #e7edf4}.work-heading{min-width:0}.work-header-actions{display:flex;align-items:center;gap:8px;flex-shrink:0}.work-title{display:flex;align-items:baseline;gap:10px}.work-title strong{font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lines{width:100%;border-collapse:collapse;table-layout:fixed}.lines th,.lines td{padding:10px 12px;border-bottom:1px solid #edf1f6;text-align:left;vertical-align:middle;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.lines th{background:#f8faff;color:#64748b;font-size:10px}.lines tr.checked{background:#f2f8ff}.lines input[type=number]{width:76px;min-height:30px;border:1px solid #cad6e6;border-radius:4px;padding:4px 6px;font:inherit}.product-code{color:#64748b;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.product-name{font-weight:800;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.location{padding:2px 5px;border-radius:3px;background:#f2f5f9;color:#475569;font-size:10px}.notice{min-height:17px;padding:10px 14px;color:#64748b;font-size:11px}.error{color:#b42318}.actions{padding:12px 14px}.primary,button{border:1px solid #cad6e6;border-radius:4px;background:#fff;color:#25344a;padding:7px 10px;font:inherit;font-size:11px;cursor:pointer}.primary{background:#0b6ff6;color:#fff;border-color:#0b6ff6;font-weight:800}.danger{border-color:#f0b7b1;color:#b42318}.empty{padding:32px 14px;text-align:center;color:#64748b}.work-empty{padding:70px 20px;text-align:center;color:#64748b}@media(min-width:1001px){.task-panel{display:flex;min-height:0;max-height:calc(100vh - 76px);max-height:calc(100dvh - 76px);flex-direction:column}.task-list{min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}}@media(max-width:1000px){.layout{grid-template-columns:1fr}}@media(max-width:640px){main{padding:8px}.task{grid-template-columns:1fr}.task-side{text-align:left}.work-header{align-items:flex-start;flex-direction:column}.lines th:nth-child(2),.lines td:nth-child(2){min-width:170px}}
    .primary:disabled,button:disabled{cursor:not-allowed;opacity:.45}.lines col.confirm-col{width:70px}.lines col.product-col{width:auto}.lines col.qty-col{width:86px}.lines col.lot-col{width:110px}.lines th:first-child,.lines td:first-child{text-align:center;padding-left:6px;padding-right:6px}.lines th:first-child{white-space:normal;overflow:visible;text-overflow:clip}.lines th:first-child input{margin-left:4px;vertical-align:middle}.lines th:nth-child(3),.lines td:nth-child(3){text-align:right}.lot-cell{display:grid;grid-template-columns:1fr;gap:4px;align-items:start}.lot-status{display:block;text-align:center;font-size:10px;font-weight:800;border-radius:999px;padding:2px 6px;background:#fee4e2;color:#b42318}.lot-status.partial{background:#fff4dd;color:#9a6700}.lot-status.done{background:#ecfdf3;color:#027a48}.lot-button{width:100%;padding:5px 7px;font-size:10px}.modal-backdrop{position:fixed;inset:0;background:rgba(15,23,42,.38);display:flex;align-items:center;justify-content:center;z-index:30}.modal-backdrop[hidden]{display:none}.lot-modal{width:min(900px,calc(100vw - 28px));max-height:calc(100vh - 40px);overflow:auto;background:#fff;border-radius:8px;border:1px solid #dce4ee;box-shadow:0 22px 70px rgba(15,23,42,.22)}.modal-head,.modal-foot{padding:12px 14px;border-bottom:1px solid #e7edf4;display:flex;align-items:center;justify-content:space-between;gap:10px}.modal-foot{border-top:1px solid #e7edf4;border-bottom:0}#lot-subtitle{display:grid;gap:2px;margin-top:4px}.lot-subtitle-product{color:#172033;font-size:16px;font-weight:800;line-height:1.35}.lot-subtitle-qty{color:#64748b;font-size:11px;font-weight:700}.modal-body{padding:12px 14px;display:grid;gap:12px}.lot-search{display:grid;grid-template-columns:minmax(280px,420px) auto 86px auto 1fr;gap:8px;align-items:end;padding:10px;border:1px solid #e7edf4;border-radius:6px;background:#fbfdff}.lot-search label{display:grid;gap:4px;font-size:10px;color:#64748b}.lot-search .lot-search-term{grid-column:1;grid-row:1;max-width:420px}.lot-search .same-capacity{grid-column:2;grid-row:1;display:flex;align-items:center;gap:6px;min-height:30px;white-space:nowrap;padding-bottom:1px}.lot-search .same-capacity input{width:auto;min-height:auto}.lot-search .lot-search-result{grid-column:1 / span 2;grid-row:2}.lot-search .lot-search-qty{grid-column:3;grid-row:2}.lot-search #add-selected-lot{grid-column:4;grid-row:2}.lot-search input,.lot-search select{border:1px solid #cad6e6;border-radius:4px;padding:7px 8px;font:inherit}.lot-search-qty input{width:86px}.lot-list{display:grid;gap:8px}.lot-row{display:grid;grid-template-columns:28px minmax(260px,1fr) 130px 138px;gap:8px;align-items:center;padding:8px;border:1px solid #edf1f6;border-radius:6px;background:#fff}.lot-index{color:#64748b;text-align:right}.lot-info strong{display:block;font-size:12px}.lot-info .muted{display:block;margin-top:2px}.lot-row input{width:86px;border:1px solid #cad6e6;border-radius:4px;padding:5px 6px;font:inherit;text-align:right}.lot-row-actions{display:flex;justify-content:flex-end;gap:6px}.approve-lot{border-color:#8bb9ef;color:#075ecf;font-weight:800}.unavailable-lots{padding:10px 12px;border:1px solid #f3b6af;border-radius:6px;background:#fff7f6;color:#912018;font-size:11px;line-height:1.6}.unavailable-lots strong{display:block;margin-bottom:3px}.unavailable-lots ul{margin:0;padding-left:18px}
  </style>
</head>
<body>
  <header><h1>出荷作業</h1><div class="actions" style="padding:0"><a href="{{route('sales-orders.index')}}">受注</a><a href="{{route('shipments.index')}}">出荷</a><span class="muted">{{$user->name}}</span></div></header>
  <main><div class="layout">
    <section class="card task-panel">
      <div class="head"><h2>出荷作業一覧</h2><div class="actions" style="padding:0"><button id="refresh-tasks" type="button">最新に更新</button><span id="task-count" class="muted"></span></div></div>
      <div class="filter"><select id="status-filter" style="min-width:150px"><option value="open">未完了</option><option value="all">すべて</option><option value="instructed">未着手</option><option value="partially_picked">作業中</option><option value="picked">完了</option></select></div>
      <div id="task-list" class="task-list"></div>
    </section>
    <section class="card">
      <div id="work-empty" class="work-empty">左の一覧から、作業する出荷指示を選択してください。</div>
      <div id="work" hidden>
        <div class="work-header"><div class="work-heading"><div class="work-title"><strong id="work-number"></strong><span id="work-status" class="badge"></span></div><p id="work-customer" class="muted" style="margin-top:5px"></p></div><div class="work-header-actions"><button id="print-work-slip" type="button" disabled>作業伝票を表示・印刷</button>@if($canCreate)<button id="save-pick" type="button" class="primary">ピッキング完了を登録</button>@endif</div></div>
        <table class="lines"><colgroup><col class="confirm-col"><col class="product-col"><col class="qty-col"><col class="lot-col"></colgroup><thead><tr><th>確認 <input id="pick-select-all" type="checkbox" aria-label="確認可能な明細をすべて選択"></th><th>商品</th><th>指示数</th><th>ロット</th></tr></thead><tbody id="line-list"></tbody></table>
        <p id="message" class="notice"></p>
        @if($canCancel)<div class="actions"><button id="cancel-pick" type="button" class="danger" hidden>直前のピッキングを取消</button></div>@endif
      </div>
    </section>
  </div></main>
  <div id="lot-modal" class="modal-backdrop" hidden>
    <section class="lot-modal" role="dialog" aria-modal="true">
      <div class="modal-head"><div><h2 id="lot-title">ロット編集</h2><p id="lot-subtitle" class="muted"></p></div></div>
      <div class="modal-body">
        <div class="actions" style="padding:0;justify-content:flex-start"><button id="auto-allocate-lots" type="button">直近取引から自動割当</button><span id="lot-message" class="muted"></span></div>
        <div id="unavailable-lots" class="unavailable-lots" hidden></div>
        <div class="lot-search">
          <label class="lot-search-term">ロット検索<input id="lot-search-text" type="search" placeholder="ロット番号・酒米・精米歩合・製造年で検索"></label>
          <label class="same-capacity"><input id="same-capacity-only" type="checkbox" checked>同一容量に限定</label>
          <label class="lot-search-result">検索結果<select id="lot-search-result"></select></label>
          <label class="lot-search-qty">数量<input id="lot-add-quantity" type="number" min="1" step="1" value="1"></label>
          <button id="add-selected-lot" type="button">追加</button>
        </div>
        <strong>指定ロット</strong>
        <div id="lot-candidates" class="lot-list"></div>
      </div>
      <div class="modal-foot"><span id="lot-total" class="muted"></span><div class="actions" style="padding:0"><button id="close-lot-modal-bottom" type="button">キャンセル</button><button id="save-lots" class="primary" type="button">保存</button></div></div>
    </section>
  </div>
  <script>
    const canCreate=@json($canCreate), canCancel=@json($canCancel), canApprove=@json($canApprove);
    const refreshSettings=@json(\App\Models\AppSetting::values(['auto_refresh_enabled'=>'1','auto_refresh_interval_seconds'=>'30']));
    const autoRefreshEnabled=refreshSettings.auto_refresh_enabled==='1';
    const autoRefreshMs=Math.max(5,Number(refreshSettings.auto_refresh_interval_seconds||30))*1000;
    const labels={instructed:'未着手',partially_picked:'作業中',picked:'完了',cancelled:'取消'};
    const api=async (url,options={})=>{const response=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{})},...options});const body=await response.json();if(!response.ok)throw new Error(body.error?.message||body.message||'処理に失敗しました');return body.data};
    let tasks=[],picks=[],selected=null,lastPick=null,isDirty=false;
    const draftKey='aikura:picking:checked-lines';
    const loadDrafts=()=>{try{return JSON.parse(localStorage.getItem(draftKey)||'{}')}catch{return {}}};
    const saveDrafts=drafts=>localStorage.setItem(draftKey,JSON.stringify(drafts));
    const draftFor=taskId=>new Set(loadDrafts()[taskId]||[]);
    const saveLineCheck=(taskId,lineId,checked)=>{const drafts=loadDrafts(),set=new Set(drafts[taskId]||[]);checked?set.add(Number(lineId)):set.delete(Number(lineId));drafts[taskId]=[...set];if(!drafts[taskId].length)delete drafts[taskId];saveDrafts(drafts)};
    const clearDraft=taskId=>{const drafts=loadDrafts();delete drafts[taskId];saveDrafts(drafts)};
    const message=(text,error=false)=>{const node=document.querySelector('#message');node.textContent=text;node.classList.toggle('error',error)};
    const markDirty=()=>{if(selected)isDirty=true};
    const clearDirty=()=>{isDirty=false};
    const confirmDiscardIfDirty=()=>!isDirty||window.confirm('登録していないピッキングがあります。保存せずに移動しますか？');
    const number=value=>String(Math.round(Number(value||0)));
    const remaining=line=>Math.max(0,Number(line.quantity||0)-Number(line.picked_quantity||0));
    const taskProgress=task=>{const total=task.lines.length,done=task.lines.filter(line=>remaining(line)<=0).length;return done+' / '+total};
    const taskStatus=task=>task.status;
    const visibleTasks=()=>{const value=document.querySelector('#status-filter').value;return tasks.filter(task=>value==='all'||(value==='open'?['instructed','partially_picked'].includes(task.status):task.status===value))};
    const updateSavePickState=()=>{const button=document.querySelector('#save-pick');if(!button)return;const checks=[...document.querySelectorAll('#line-list input[type=checkbox]')];button.disabled=!selected||!checks.length||checks.some(check=>!check.checked);updatePickSelectAllState()};
    const updatePickSelectAllState=()=>{const control=document.querySelector('#pick-select-all');if(!control)return;const checks=[...document.querySelectorAll('#line-list input[type=checkbox]')],targets=checks.filter(check=>!check.disabled);const selectedCount=targets.filter(check=>check.checked).length;control.checked=targets.length>0&&selectedCount===targets.length;control.indeterminate=selectedCount>0&&selectedCount<targets.length;control.disabled=targets.length===0};
    const togglePickSelectAll=checked=>{if(!selected)return;[...document.querySelectorAll('#line-list input[type=checkbox]')].filter(check=>!check.disabled).forEach(check=>{check.checked=checked;check.closest('tr')?.classList.toggle('checked',checked);saveLineCheck(selected.id,check.dataset.lineId,checked)});clearDirty();updateSavePickState()};
    const isLotReady=line=>Number(line.lot_allocated_quantity||0)>=Number(line.quantity||0);
    const lotLabel=line=>{const allocated=Number(line.lot_allocated_quantity||0),required=Number(line.quantity||0);if(allocated<=0)return ['未割当',''];if(allocated<required)return ['一部割当','partial'];return ['割当済','done']};
    const renderTasks=()=>{const list=document.querySelector('#task-list'),items=visibleTasks();document.querySelector('#task-count').textContent=items.length+'件';list.replaceChildren(...items.map(task=>{const button=document.createElement('button');button.className='task'+(selected?.id===task.id?' selected':'');button.type='button';button.onclick=()=>selectTask(task);const main=document.createElement('div');main.className='task-main';const top=document.createElement('div');top.className='task-top';const no=document.createElement('span');no.className='task-number';no.textContent=task.sales_order_number||task.instruction_number;const badge=document.createElement('span');badge.className='badge '+(task.status==='partially_picked'?'progress':task.status==='picked'?'done':task.status==='cancelled'?'danger':'');badge.textContent=labels[taskStatus(task)]||taskStatus(task);top.append(no,badge);const customer=document.createElement('div');customer.className='task-customer';customer.textContent=task.customer_name||'取引先未設定';main.append(top,customer);const side=document.createElement('div');side.className='task-side';side.innerHTML='<span>出荷予定日</span><strong>'+(task.scheduled_shipment_date||'—')+'</strong><span>出荷拠点</span><strong>'+(task.stock_location_name||'未設定')+'</strong><span>進捗</span><strong>'+taskProgress(task)+'</strong>';button.append(main,side);return button}));if(!items.length)list.innerHTML='<div class="empty">対象の出荷作業はありません。</div>'};
    const clearWork=()=>{selected=null;lastPick=null;document.querySelector('#work-empty').hidden=false;document.querySelector('#work').hidden=true;document.querySelector('#line-list').replaceChildren();document.querySelector('#print-work-slip').disabled=true;document.querySelector('#cancel-pick')?.setAttribute('hidden','hidden');message('左の一覧から、作業する出荷指示を選択してください。')};
    const selectTask=async task=>{selected=task;clearDirty();lastPick=picks.find(pick=>pick.shipment_instruction_id===task.id&&pick.status==='picked'&&!pick.shipment_header_id)||null;document.querySelector('#work-empty').hidden=true;document.querySelector('#work').hidden=false;document.querySelector('#work-number').textContent=task.sales_order_number||task.instruction_number;document.querySelector('#work-customer').textContent=task.customer_name||'';const badge=document.querySelector('#work-status');badge.textContent=labels[task.status]||task.status;badge.className='badge '+(task.status==='partially_picked'?'progress':task.status==='picked'?'done':task.status==='cancelled'?'danger':'');document.querySelector('#print-work-slip').disabled=false;document.querySelector('#cancel-pick')?.toggleAttribute('hidden',!lastPick);renderLines();renderTasks();message('確認チェックは一時保存されます。すべての確認が済むとピッキング完了を登録できます。')};
    const renderLines=()=>{const tbody=document.querySelector('#line-list');const draft=draftFor(selected.id);tbody.replaceChildren(...selected.lines.map(line=>{const row=document.createElement('tr'),left=remaining(line),isComplete=left<=0,lotReady=isLotReady(line),isDraftChecked=lotReady&&draft.has(Number(line.id));if(isComplete||isDraftChecked)row.className='checked';const check=document.createElement('input');check.type='checkbox';check.checked=isComplete||isDraftChecked;check.disabled=isComplete||!lotReady;check.title=!lotReady?'ロット割当が完了すると確認できます':'';check.dataset.lineId=line.id;check.dataset.quantity=number(left);const checkCell=document.createElement('td');checkCell.append(check);const product=document.createElement('td');product.innerHTML='<div class="product-code">'+(line.product_code||'—')+'</div><div class="product-name">'+(line.product_name||'商品')+'</div>';product.style.cursor=isComplete||!lotReady?'default':'pointer';product.onclick=()=>{if(check.disabled)return;check.checked=!check.checked;check.dispatchEvent(new Event('change'))};const qty=document.createElement('td');qty.textContent=number(line.quantity)+' '+(line.unit_name||line.unit_code||'');const lot=document.createElement('td');const [label,klass]=lotLabel(line);lot.innerHTML='<div class="lot-cell"><span class="lot-status '+klass+'">'+label+'</span><button class="lot-button" type="button">ロット編集</button></div>';lot.querySelector('button').onclick=event=>{event.stopPropagation();openLotEditor(line)};check.onchange=()=>{row.classList.toggle('checked',check.checked);saveLineCheck(selected.id,line.id,check.checked);clearDirty();updateSavePickState()};row.append(checkCell,product,qty,lot);return row}));updateSavePickState()};
    const load=async()=>{const refresh=document.querySelector('#refresh-tasks');try{if(refresh){refresh.disabled=true;refresh.textContent='更新中...'}const [instructionData,pickData]=await Promise.all([api('/api/v1/shipment-instructions'),api('/api/v1/shipment-picks')]);tasks=instructionData.shipment_instructions.filter(task=>['instructed','partially_picked','picked'].includes(task.status));picks=pickData.shipment_picks;if(selected)selected=tasks.find(task=>task.id===selected.id)||null;renderTasks();const visibleIds=new Set(visibleTasks().map(task=>task.id));if(selected&&visibleIds.has(selected.id))selectTask(selected);else clearWork();document.querySelector('#task-count').textContent=visibleTasks().length+'件 / 更新 '+new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}catch(error){message(error.message,true)}finally{if(refresh){refresh.disabled=false;refresh.textContent='最新に更新'}}};
    let lotEditor=null;
    const lotModal=document.querySelector('#lot-modal');
    const lotSum=()=>[...document.querySelectorAll('#lot-candidates input[data-lot-id]')].reduce((sum,input)=>sum+Number(input.value||0),0);
    const updateLotSaveState=()=>{const button=document.querySelector('#save-lots');if(button)button.disabled=!lotEditor||lotSum()<=0};
    const updateLotTotal=()=>{if(!lotEditor)return;document.querySelector('#lot-total').textContent='現在の割当 合計 ['+number(lotSum())+'] / 指示数量 '+number(lotEditor.line.quantity);updateLotSaveState()};
    const lotText=candidate=>{const date=candidate.production_date||candidate.bottling_date||'—',recent=Number(candidate.recent_quantity||0)>0?' / 直近'+number(candidate.recent_quantity):'',alcohol=candidate.alcohol_percentage!==null?' / '+candidate.alcohol_percentage+'%':' / 度数未確定',state=candidate.alcohol_compliance_status==='out_of_range'?' / 許容外':candidate.alcohol_compliance_status==='analysis_required'?' / 分析未確定':'';return (candidate.display_name||candidate.lot_code)+' / 在庫'+number(candidate.available_quantity)+alcohol+state+' / 入庫日 '+date+recent};
    const lotSearchText=candidate=>[candidate.lot_code,candidate.display_name,candidate.production_date,candidate.bottling_date,candidate.rice_variety,candidate.rice_polishing_ratio,candidate.production_method,candidate.alcohol_percentage].filter(value=>value!==null&&value!=='').join(' ').toLowerCase();
    const sameCapacity=(candidate,target)=>!target?.capacity_value||!target?.capacity_unit_id||(Number(candidate.capacity_value||0)===Number(target.capacity_value||0)&&Number(candidate.capacity_unit_id||0)===Number(target.capacity_unit_id||0));
    const updateLotSearch=()=>{if(!lotEditor)return;const select=document.querySelector('#lot-search-result'),term=(document.querySelector('#lot-search-text')?.value||'').toLowerCase(),sameOnly=document.querySelector('#same-capacity-only')?.checked,target=lotEditor.data.shipment_line;const candidates=(lotEditor.data.candidates||[]).filter(candidate=>candidate.selectable!==false&&Number(candidate.current_quantity||0)<=0&&(!sameOnly||sameCapacity(candidate,target))&&(!term||lotSearchText(candidate).includes(term)));select.replaceChildren();if(!candidates.length){select.append(new Option('該当するロットがありません',''));return}candidates.slice(0,80).forEach(candidate=>select.append(new Option(lotText(candidate),String(candidate.production_lot_id))))};
    const renderUnavailableLots=()=>{const box=document.querySelector('#unavailable-lots'),rows=(lotEditor?.data?.candidates||[]).filter(candidate=>candidate.selectable===false&&Number(candidate.current_quantity||0)<=0);box.hidden=!rows.length;if(!rows.length){box.replaceChildren();return}box.innerHTML='<strong>選択できない在庫ロット</strong><ul>'+rows.map(candidate=>'<li>'+esc(lotText(candidate))+' / '+esc(candidate.non_selectable_reason||'選択できません。')+'</li>').join('')+'</ul>'};
    const renderLotCandidates=()=>{const list=document.querySelector('#lot-candidates');const candidates=lotEditor.data.candidates||[];const selectedLots=candidates.filter(candidate=>Number(candidate.current_quantity||0)>0);const nodes=selectedLots.map((candidate,index)=>{const row=document.createElement('div');row.className='lot-row';row.innerHTML='<div class="lot-index"></div><div class="lot-info"><strong></strong><span class="muted"></span></div><label>数量<input type="number" min="0" step="1"></label><div class="lot-row-actions"><button type="button" class="approve-lot" hidden>承認</button><button type="button" class="danger remove-lot">削除</button></div>';row.querySelector('.lot-index').textContent=String(index+1);row.querySelector('strong').textContent=lotText(candidate);row.querySelector('.muted').textContent=[candidate.lot_code,candidate.rice_variety,candidate.rice_polishing_ratio?candidate.rice_polishing_ratio+'%':null,candidate.allowed_alcohol_min!==null?'許容 '+candidate.allowed_alcohol_min+'～'+candidate.allowed_alcohol_max+'%':null,candidate.approval_status==='pending'?'承認待ち':candidate.approval_status==='approved'?'承認済み':null].filter(Boolean).join(' / ');const input=row.querySelector('input');input.dataset.lotId=candidate.production_lot_id;input.dataset.available=Number(candidate.available_quantity||0);input.value=number(candidate.current_quantity);input.addEventListener('input',()=>{candidate.current_quantity=Number(input.value||0);updateLotTotal()});const approve=row.querySelector('.approve-lot');approve.hidden=!(canApprove&&candidate.approval_status==='pending'&&candidate.approval_request_id);approve.onclick=async()=>{approve.disabled=true;document.querySelector('#lot-message').textContent='承認中...';try{await api('/api/v1/approval-requests/'+candidate.approval_request_id+'/approve',{method:'POST',body:JSON.stringify({comment:'ピッキング画面で許容範囲外ロットを承認'})});await openLotEditor(lotEditor.line);document.querySelector('#lot-message').textContent='許容範囲外ロットを承認しました。'}catch(error){approve.disabled=false;document.querySelector('#lot-message').textContent=error.message}};row.querySelector('.remove-lot').onclick=()=>{candidate.current_quantity=0;renderLotCandidates()};return row});list.replaceChildren(...nodes);if(!selectedLots.length)list.innerHTML='<p class="muted">指定ロットはまだありません。直前のロット割当を参考に指定します。</p>';renderUnavailableLots();updateLotSearch();updateLotTotal()};
    const openLotEditor=async line=>{if(!selected)return;lotEditor={line,data:null};lotModal.hidden=false;document.querySelector('#lot-title').textContent='ロット編集';document.querySelector('#lot-subtitle').replaceChildren(Object.assign(document.createElement('span'),{className:'lot-subtitle-product',textContent:line.product_name||'商品'}),Object.assign(document.createElement('span'),{className:'lot-subtitle-qty',textContent:'指示数量 '+number(line.quantity)}));document.querySelector('#lot-message').textContent='候補を読み込み中...';document.querySelector('#lot-candidates').replaceChildren();document.querySelector('#lot-search-text').value='';document.querySelector('#same-capacity-only').checked=true;document.querySelector('#lot-add-quantity').value=number(line.quantity);document.querySelector('#lot-search-result').replaceChildren();updateLotSaveState();try{const data=await api('/api/v1/shipment-instructions/'+selected.id+'/lines/'+line.id+'/lots');lotEditor.data=data;const recent=data.recent_allocation||{};document.querySelector('#lot-message').textContent=recent.shipment_document_number?'直前のロット割当を参考に指定します。直近: '+recent.shipment_document_number+' / '+(recent.transaction_date||'日付なし'):'直前のロット割当を参考に指定します。直近取引がない場合は検索して指定してください。';renderLotCandidates()}catch(error){document.querySelector('#lot-message').textContent=error.message;updateLotSaveState()}};
    const closeLotEditor=()=>{lotModal.hidden=true;lotEditor=null};
    const autoAllocateLots=()=>{if(!lotEditor)return;const recent=(lotEditor.data.recent_allocation?.allocations||[]);if(!recent.length){document.querySelector('#lot-message').textContent='参考にできる直近取引のロット割当がありません。検索して指定してください。';return}let remainingQty=Number(lotEditor.line.quantity||0);(lotEditor.data.candidates||[]).forEach(candidate=>candidate.current_quantity=0);recent.forEach(row=>{if(remainingQty<=0)return;const candidate=(lotEditor.data.candidates||[]).find(item=>String(item.production_lot_id)===String(row.production_lot_id));if(!candidate)return;const qty=Math.max(0,Math.min(Number(candidate.available_quantity||0),remainingQty));candidate.current_quantity=qty;remainingQty-=qty});document.querySelector('#lot-message').textContent=remainingQty>0?'直近取引のロットを参考に、今回の指示数量で割当しました。不足分は検索して追加してください。':'直近取引のロットを参考に、今回の指示数量で割当しました。';renderLotCandidates()};
    const clearLots=()=>{(lotEditor?.data?.candidates||[]).forEach(candidate=>candidate.current_quantity=0);renderLotCandidates()};
    const addSelectedLot=()=>{if(!lotEditor)return;const lotId=document.querySelector('#lot-search-result')?.value;if(!lotId)return;const candidate=(lotEditor.data.candidates||[]).find(item=>String(item.production_lot_id)===String(lotId));if(!candidate)return;const qty=Number(document.querySelector('#lot-add-quantity')?.value||0);if(qty<=0)return document.querySelector('#lot-message').textContent='追加する数量を入力してください。';candidate.current_quantity=Math.min(Number(candidate.available_quantity||0),qty);document.querySelector('#lot-add-quantity').value=number(Math.max(0,Number(lotEditor.line.quantity||0)-lotSum()));renderLotCandidates()};
    const saveLots=async()=>{if(!lotEditor||!selected)return;const line=lotEditor.line,total=lotSum();if(total<=0)return document.querySelector('#lot-message').textContent='ロットを追加してから保存してください。';if(total>Number(line.quantity||0))return document.querySelector('#lot-message').textContent='割当数量が指示数量を超えています。';const selectedCandidates=(lotEditor.data.candidates||[]).filter(candidate=>Number(candidate.current_quantity||0)>0);if(selectedCandidates.some(candidate=>candidate.alcohol_compliance_status==='analysis_required'))return document.querySelector('#lot-message').textContent='アルコール分析が確定していないロットは選択できません。';let reason='ピッキング画面でのロット編集';if(selectedCandidates.some(candidate=>candidate.alcohol_compliance_status==='out_of_range')){reason=window.prompt('許容範囲外ロットは別明細に分割され、管理者承認が必要です。使用理由を入力してください。','規格外ロットを使用するため');if(!reason?.trim())return document.querySelector('#lot-message').textContent='規格外ロットの使用理由を入力してください。'}const allocations=[...document.querySelectorAll('#lot-candidates input[data-lot-id]')].map(input=>({production_lot_id:Number(input.dataset.lotId),quantity:Number(input.value||0)}));document.querySelector('#lot-message').textContent='保存中...';try{const data=await api('/api/v1/shipment-instructions/'+selected.id+'/lines/'+line.id+'/lots',{method:'PUT',body:JSON.stringify({allocations,reason})});line.lot_allocated_quantity=(data.allocations||[]).reduce((sum,row)=>sum+Number(row.quantity||0),0);const pending=(data.allocations||[]).filter(row=>row.approval_status==='pending').length;document.querySelector('#lot-message').textContent=pending?'別明細へ分割し、管理者承認を申請しました。':'保存しました。';renderLines();setTimeout(closeLotEditor,pending?900:250)}catch(error){document.querySelector('#lot-message').textContent=error.message}};
    document.querySelector('#status-filter').onchange=()=>{clearDirty();renderTasks();if(selected&&!visibleTasks().some(task=>task.id===selected.id))clearWork()};
    document.querySelector('#pick-select-all')?.addEventListener('change',event=>togglePickSelectAll(event.target.checked));
    document.querySelector('#print-work-slip')?.addEventListener('click',()=>{if(!selected)return;window.open('/shipment-instructions/'+selected.id+'/work-slip','_blank')});
    document.querySelector('#close-lot-modal')?.addEventListener('click',closeLotEditor);
    document.querySelector('#close-lot-modal-bottom')?.addEventListener('click',closeLotEditor);
    document.querySelector('#auto-allocate-lots')?.addEventListener('click',autoAllocateLots);
    document.querySelector('#lot-search-text')?.addEventListener('input',updateLotSearch);
    document.querySelector('#same-capacity-only')?.addEventListener('change',updateLotSearch);
    document.querySelector('#add-selected-lot')?.addEventListener('click',addSelectedLot);
    document.querySelector('#clear-lots')?.addEventListener('click',clearLots);
    document.querySelector('#save-lots')?.addEventListener('click',saveLots);
    document.querySelector('#lot-modal')?.addEventListener('click',event=>{if(event.target.id==='lot-modal')closeLotEditor()});
    window.addEventListener('keydown',event=>{if(event.key==='Escape'&&!lotModal.hidden)closeLotEditor()});
    document.querySelector('#save-pick')?.addEventListener('click',async()=>{if(!selected)return;updateSavePickState();if(document.querySelector('#save-pick')?.disabled)return message('すべての確認にチェックを付けてから登録してください。',true);const taskId=selected.id;const lines=[...document.querySelectorAll('#line-list input[type=checkbox]:checked:not(:disabled)')].map(check=>({shipment_instruction_line_id:Number(check.dataset.lineId),quantity:check.dataset.quantity}));if(!lines.length)return message('確認対象の商品がありません。',true);message('ピッキング完了を登録中です。');try{await api('/api/v1/shipment-picks',{method:'POST',body:JSON.stringify({shipment_instruction_id:taskId,pick_date:new Date().toISOString().slice(0,10),lines})});clearDraft(taskId);clearDirty();selected=null;clearWork();message('ピッキング完了を登録しました。');await load()}catch(error){message(error.message,true)}});
    document.querySelector('#cancel-pick')?.addEventListener('click',async()=>{if(!lastPick||!canCancel)return;const reason=window.prompt('取消理由を入力してください。');if(reason===null)return;if(!reason.trim())return message('取消理由を入力してください。',true);try{await api('/api/v1/shipment-picks/'+lastPick.id+'/cancel',{method:'POST',body:JSON.stringify({reason})});message('直前のピッキングを取り消しました。');await load()}catch(error){message(error.message,true)}});
    const addOverflowTitles=(root=document)=>root.querySelectorAll('td,th,.task-number,.task-customer,.task-side,.badge,.product-code,.product-name,#work-number,#work-customer').forEach(el=>{const text=el.textContent.trim();if(text)el.title=text});
    new MutationObserver(mutations=>mutations.forEach(mutation=>mutation.addedNodes.forEach(node=>{if(node.nodeType===1)addOverflowTitles(node)}))).observe(document.body,{childList:true,subtree:true});
    document.querySelector('#refresh-tasks')?.addEventListener('click',()=>{if(confirmDiscardIfDirty())load()});
    window.addEventListener('beforeunload',event=>{if(!isDirty)return;event.preventDefault();event.returnValue=''});
    load();
    if(autoRefreshEnabled)setInterval(()=>{ if(!selected){ load(); } },autoRefreshMs);
  </script>
</body></html>
